def sum_largest_prime_substrings(s: str) -> int:
    # Helper function: Primality test (for numbers up to 10**10),
    # Using deterministic Miller-Rabin bases covering 64-bit
    def is_prime(n):
        if n < 2: return False
        if n in (2, 3): return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        if n < 1373653:
            for a in (2, 3):
                if not miller_rabin_base(n, a):
                    return False
            return True
        # For up to 32-bit, these are sufficient bases
        for a in (2, 3, 5, 7, 11):
            if not miller_rabin_base(n, a):
                return False
        return True

    # Miller-Rabin base test
    def miller_rabin_base(n, a):
        d, s = n-1, 0
        while d % 2 == 0:
            d //= 2
            s += 1
        x = pow(a, d, n)
        if x == 1 or x == n-1:
            return True
        for _ in range(s-1):
            x = pow(x, 2, n)
            if x == n-1:
                return True
        return False

    primes = set()
    n = len(s)
    for i in range(n):
        for j in range(i+1, n+1):
            val = int(s[i:j])  # leading zeros ignored by int()
            if is_prime(val):
                primes.add(val)
    if not primes:
        return 0
    largest = sorted(primes, reverse=True)[:3]
    return sum(largest)
